#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cctype>

using namespace std;

int remove_underscore(string &str) {
    // Replace all underscores with spaces
    for (char &ch : str) {
        if (ch == '_') ch = ' ';
    }
    // Trim leading and trailing spaces
    size_t start = str.find_first_not_of(' ');
    size_t end = str.find_last_not_of(' ');
    if (start == string::npos || end == string::npos) {
        str = "";
        return 0;
    }
    str = str.substr(start, end - start + 1);
    // Replace multiple spaces with a single space
    string result;
    bool in_space = false;
    for (char ch : str) {
        if (isspace(ch)) {
            if (!in_space) {
                result += ' ';
                in_space = true;
            }
        } else {
            result += ch;
            in_space = false;
        }
    }
    str = result;
    if (str.empty()) return 0;
    // Count words
    int count = 1;
    for (char ch : str) {
        if (ch == ' ') count++;
    }
    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;

    vector<int> braces_indices;
    braces_indices.push_back(-1);
    for (int i = 0; i < (int)s.length(); i++) {
        if (s[i] == '(' || s[i] == ')') {
            braces_indices.push_back(i);
        }
    }

    int count_inside_braces = 0;
    int maxl = 0;
    string outside_braces = "";

    int i = 1;
    while (i < (int)braces_indices.size() - 1) {
        int open_brace_index = braces_indices[i];
        int close_brace_index = braces_indices[i + 1];
        string inside_braces = s.substr(open_brace_index + 1, close_brace_index - open_brace_index - 1);
        int count = remove_underscore(inside_braces);
        count_inside_braces += count;
        int prev_index = braces_indices[i - 1];
        int curr_index = open_brace_index;
        outside_braces += "_" + s.substr(prev_index + 1, curr_index - prev_index - 1);
        i += 2;
    }
    // Append the remaining part after the last closing brace
    int last_index = braces_indices.back();
    outside_braces += "_" + s.substr(last_index + 1);
    // Replace underscores with spaces
    for (char &ch : outside_braces) {
        if (ch == '_') ch = ' ';
    }
    // Trim leading and trailing spaces
    size_t start = outside_braces.find_first_not_of(' ');
    size_t end = outside_braces.find_last_not_of(' ');
    if (start != string::npos && end != string::npos) {
        outside_braces = outside_braces.substr(start, end - start + 1);
    } else {
        outside_braces = "";
    }
    // Replace multiple spaces with a single space
    string cleaned;
    bool in_space = false;
    for (char ch : outside_braces) {
        if (isspace(ch)) {
            if (!in_space) {
                cleaned += ' ';
                in_space = true;
            }
        } else {
            cleaned += ch;
            in_space = false;
        }
    }
    outside_braces = cleaned;

    // Split into words and find max length
    if (!outside_braces.empty()) {
        size_t pos = 0;
        while (pos < outside_braces.length()) {
            size_t space_pos = outside_braces.find(' ', pos);
            if (space_pos == string::npos) {
                string word = outside_braces.substr(pos);
                if ((int)word.length() > maxl) maxl = word.length();
                break;
            } else {
                string word = outside_braces.substr(pos, space_pos - pos);
                if ((int)word.length() > maxl) maxl = word.length();
                pos = space_pos + 1;
            }
        }
    }

    cout << maxl << " " << count_inside_braces;
    return 0;
}

